--
-- Name: assert_org_within_seats(uuid); Type: FUNCTION; Schema: app_security; Owner: -
--

CREATE FUNCTION payroll_iq.assert_org_within_seats(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_seats integer;
  v_used  integer;
begin
  -- Admins are orgless by CHECK and never learners; nothing to enforce.
  if p_org_id is null then
    return;
  end if;

  select o.learner_seats into v_seats
    from payroll_iq.organisations o
   where o.id = p_org_id
     for update;

  -- No org row: the foreign key will raise a better error than we can.
  if v_seats is null then
    return;
  end if;

  v_used := payroll_iq.org_seats_used(p_org_id);

  if v_used > v_seats then
    raise exception 'seat_limit_reached: % of % seats in use', v_used, v_seats
      using errcode = 'check_violation',
            hint = 'seat_limit_reached';
  end if;
end;
$$;


