CREATE FUNCTION payroll_iq.org_seats_used(p_org_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (
    (select count(*)
       from payroll_iq.users u
      where u.org_id = p_org_id
        and u.status = 'active'
        and u.is_learner)
  + (select count(*)
       from payroll_iq.invites i
      where i.org_id = p_org_id
        and i.is_learner
        and i.released_at is null
        and i.expires_at > now())
  )::integer;
$$;


