--
-- Name: organisations_guard_billing(); Type: FUNCTION; Schema: app_security; Owner: -
--

CREATE FUNCTION payroll_iq.organisations_guard_billing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or payroll_iq.is_admin() then
    return new;
  end if;

  if new.billing_lane              is distinct from old.billing_lane
  or new.billing_state             is distinct from old.billing_state
  or new.paid_through              is distinct from old.paid_through
  or new.grace_ends_on             is distinct from old.grace_ends_on
  or new.stripe_customer_id        is distinct from old.stripe_customer_id
  or new.stripe_subscription_id    is distinct from old.stripe_subscription_id
  or new.hubspot_invoice_ref       is distinct from old.hubspot_invoice_ref
  or new.seat_price_override_cents is distinct from old.seat_price_override_cents then
    raise exception 'only an administrator may change billing fields'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;


--
-- Name: organisations_guard_seats(); Type: FUNCTION; Schema: app_security; Owner: -
--

CREATE FUNCTION payroll_iq.organisations_guard_seats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or payroll_iq.is_admin() then
    return new;
  end if;

  if new.learner_seats > old.learner_seats then
    raise exception 'only an administrator may add seats'
      using errcode = 'insufficient_privilege',
            hint = 'seat_increase_requires_admin';
  end if;

  if new.learner_seats < old.learner_seats
     and not payroll_iq.is_org_manager(old.id) then
    raise exception 'only an org manager or administrator may change seats'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;


