--
-- Name: users_guard_privileged_columns(); Type: FUNCTION; Schema: app_security; Owner: -
--

CREATE FUNCTION payroll_iq.users_guard_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or payroll_iq.is_admin() then
    return new;
  end if;

  if new.role   is distinct from old.role
  or new.org_id is distinct from old.org_id
  or new.email  is distinct from old.email then
    raise exception 'only admins may change role, org, or email';
  end if;

  if new.status is distinct from old.status
     and not (old.org_id is not null
              and payroll_iq.is_org_manager(old.org_id)) then
    raise exception 'only an org manager or admin may change member status';
  end if;

  return new;
end;
$$;


--
-- Name: admin_org_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION payroll_iq.admin_org_directory() RETURNS TABLE(id uuid, slug text, name text, status text, created_at timestamp with time zone, learner_seats integer, seats_used integer, learner_count integer, manager_count integer, open_invite_count integer, deactivated_count integer, manager_user_id uuid, manager_name text, manager_email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- service_role is a trusted server-side caller: it reaches this only
  -- from code that has already run `requireAdmin`, and it can read every
  -- underlying table directly regardless. Refusing it bought no safety
  -- and broke the page. (Same reasoning as 008 on org_seat_usage.)
  if not (
    auth.role() = 'service_role'
    or payroll_iq.is_admin()
  ) then
    raise exception 'not authorised to list organisations'
      using errcode = 'insufficient_privilege';
  end if;

  return query
    select
      o.id,
      o.slug,
      o.name,
      o.status,
      o.created_at,
      o.learner_seats,
      payroll_iq.org_seats_used(o.id),
      (select count(*)::integer from payroll_iq.users u
        where u.org_id = o.id and u.status = 'active' and u.is_learner),
      (select count(*)::integer from payroll_iq.users u
        where u.org_id = o.id and u.status = 'active' and u.role = 'manager'),
      (select count(*)::integer from payroll_iq.invites i
        where i.org_id = o.id
          and i.released_at is null
          and i.expires_at > now()),
      (select count(*)::integer from payroll_iq.users u
        where u.org_id = o.id and u.status = 'deactivated'),
      m.id,
      m.full_name,
      m.email
    from payroll_iq.organisations o
    left join lateral (
      select u.id, u.full_name, u.email
        from payroll_iq.users u
       where u.org_id = o.id
         and u.role = 'manager'
         and u.status = 'active'
       order by u.created_at asc
       limit 1
    ) m on true
    order by o.name asc;
end;
$$;


