--
-- Name: topics_one_level_deep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION payroll_iq.topics_one_level_deep() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.parent_id is null then
    return new;
  end if;

  if exists (
    select 1 from payroll_iq.topics p
     where p.id = new.parent_id
       and p.parent_id is not null
  ) then
    raise exception
      'topic hierarchy is one level deep: % already has a parent, so it cannot be one',
      new.parent_id
      using errcode = 'check_violation', hint = 'topic_depth_exceeded';
  end if;

  if exists (
    select 1 from payroll_iq.topics c
     where c.parent_id = new.id
  ) then
    raise exception
      'topic hierarchy is one level deep: this topic already has sub-topics, so it cannot become one'
      using errcode = 'check_violation', hint = 'topic_depth_exceeded';
  end if;

  return new;
end;
$$;


--
-- Name: touch_last_seen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION payroll_iq.touch_last_seen() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    return;
  end if;
  update payroll_iq.users
     set last_seen_at = now()
   where id = auth.uid()
     and status = 'active'
     and (last_seen_at is null
       or last_seen_at < now() - interval '1 hour');
end;
$$;


