-- Name: FUNCTION touch_last_seen(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION payroll_iq.touch_last_seen() IS 'Record that the calling user is here, at most once an hour. No-ops otherwise, so it is safe to call on every authenticated page render.';


