    CONSTRAINT cycles_status_check CHECK ((status = ANY (ARRAY['active'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT cycles_track_snapshot_check CHECK ((track_snapshot = ANY (ARRAY['payroll'::text, 'hr'::text]))),
    CONSTRAINT cycles_weekly_minutes_check CHECK ((weekly_minutes = ANY (ARRAY[10, 15, 20, 30, 40, 50, 60, 90, 120])))
);


--
-- Name: COLUMN cycles.weekly_minutes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.cycles.weekly_minutes IS 'Commitment SNAPSHOT for this cycle (v2, from the program plan). users.weekly_minutes is the current preference; changing it mid-cycle does not rewrite the running cycle''s budget.';


--
-- Name: COLUMN cycles.states_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.cycles.states_snapshot IS 'The organisation''s operating_states at cycle start. Frozen for the same reason as track_snapshot: an admin correcting the org record must not rewrite a plan someone is halfway through. NULL means the cycle predates state scoping and was generated from general content only.';


--
-- Name: discount_codes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.discount_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    percent numeric(5,2) NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT discount_codes_percent_check CHECK (((percent > (0)::numeric) AND (percent <= (100)::numeric)))
);


--
-- Name: TABLE discount_codes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.discount_codes IS 'Admin-managed discount codes, applied by admin/sales when raising 21+ invoices — shown as a discount line on the invoice. There is NO public promo-code box in checkout, by decision (C5); do not add a redemption path from buyer surfaces.';


--
-- Name: hubspot_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.hubspot_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    dedupe_key text NOT NULL,
    payload jsonb NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    delivered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hubspot_outbox_kind_check CHECK ((kind = ANY (ARRAY['invoice_copy'::text, 'mark_paid'::text, 'cancel_flag'::text])))
);


--
-- Name: TABLE hubspot_outbox; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.hubspot_outbox IS 'Queued writes to HubSpot (Stripe-lane paid copies, mark-paid write-throughs, cancellation flags), drained by the outbox cron with retry/backoff. Written only by service_role. The purchase path enqueues and moves on — it never awaits HubSpot (I3). Rows undelivered past 24h surface as an admin notification.';


--
-- Name: ingest_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.ingest_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    external_id text NOT NULL,
    module_id uuid,
    outcome text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ingest_items_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['created'::text, 'updated'::text, 'ignored'::text, 'error'::text]))))
);


--
-- Name: TABLE ingest_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.ingest_items IS 'Generic ingest work items (outcome null while pending). payload carries AI-2 tag proposals and AI-3 draft-question material; the settled provider id lands on modules.external_video_id.';


--
-- Name: ingest_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.ingest_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    triggered_by uuid,
    status text DEFAULT 'running'::text NOT NULL,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT ingest_runs_finished_consistency CHECK (((status = 'running'::text) = (finished_at IS NULL))),
    CONSTRAINT ingest_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'succeeded'::text, 'failed'::text])))
);


--
-- Name: invites; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.invites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    invited_by uuid,
    email text NOT NULL,
    full_name text,
    phone text,
    role text DEFAULT 'learner'::text NOT NULL,
    token text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    accepted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone,
    is_learner boolean DEFAULT true NOT NULL,
    CONSTRAINT invites_accepted_is_released CHECK (((accepted_at IS NULL) OR (released_at IS NOT NULL))),
    CONSTRAINT invites_role_check CHECK ((role = ANY (ARRAY['manager'::text, 'learner'::text])))
);


--
-- Name: TABLE invites; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.invites IS 'Manager adds team members by name/email/phone. Acceptance runs server-side (service role): creates the users row with the invited role and stamps accepted_at. Admin invites do not exist — admins are created by admins.';


--
-- Name: COLUMN invites.released_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.invites.released_at IS 'When this invite stopped holding a seat: accepted or revoked. NULL while it is still open. Expiry does not set this — occupancy reads expires_at directly.';


--
-- Name: invoice_records; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.invoice_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    origin text NOT NULL,
    external_id text NOT NULL,
    kind text DEFAULT 'purchase'::text NOT NULL,
    seats integer NOT NULL,
    net_cents integer NOT NULL,
    gst_cents integer NOT NULL,
    total_cents integer NOT NULL,
    currency text DEFAULT 'AUD'::text NOT NULL,
    status text DEFAULT 'issued'::text NOT NULL,
    issued_on date NOT NULL,
    paid_on date,
    grace_ends_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoice_records_check CHECK ((total_cents = (net_cents + gst_cents))),
    CONSTRAINT invoice_records_gst_cents_check CHECK ((gst_cents >= 0)),
    CONSTRAINT invoice_records_kind_check CHECK ((kind = ANY (ARRAY['purchase'::text, 'renewal'::text, 'seat_addition'::text]))),
    CONSTRAINT invoice_records_net_cents_check CHECK ((net_cents >= 0)),
    CONSTRAINT invoice_records_origin_check CHECK ((origin = ANY (ARRAY['stripe'::text, 'hubspot'::text]))),
    CONSTRAINT invoice_records_paid_has_date CHECK (((status <> 'paid'::text) OR (paid_on IS NOT NULL))),
    CONSTRAINT invoice_records_seats_check CHECK ((seats >= 1)),
    CONSTRAINT invoice_records_status_check CHECK ((status = ANY (ARRAY['issued'::text, 'paid'::text])))
);


--
-- Name: TABLE invoice_records; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.invoice_records IS 'App-side ledger of invoices from both lanes (rows written only by service_role: webhooks, crons and admin server actions — do not "fix" the missing write policies). The (origin, external_id) uniqueness is the idempotency anchor for webhook replays and double-clicked mark-paid. There is deliberately NO ''void'' or ''refunded'' status: the app never voids, refunds or writes off (G3) — those are finance decisions made offline in HubSpot/Xero.';


--
-- Name: levels; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.levels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'live'::text NOT NULL,
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT levels_retired_consistency CHECK (((status = 'retired'::text) = (retired_at IS NOT NULL))),
    CONSTRAINT levels_status_check CHECK ((status = ANY (ARRAY['live'::text, 'retired'::text])))
);


--
-- Name: module_progress; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.module_progress (
    learner_id uuid NOT NULL,
    module_id uuid NOT NULL,
    resume_seconds integer DEFAULT 0 NOT NULL,
    max_seconds integer DEFAULT 0 NOT NULL,
    state text DEFAULT 'not_started'::text NOT NULL,
    started_at timestamp with time zone,
    last_played_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT module_progress_completed_consistency CHECK (((state = 'completed'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT module_progress_max_seconds_check CHECK ((max_seconds >= 0)),
    CONSTRAINT module_progress_resume_seconds_check CHECK ((resume_seconds >= 0)),
    CONSTRAINT module_progress_started_consistency CHECK (((state = 'not_started'::text) = (started_at IS NULL))),
    CONSTRAINT module_progress_state_check CHECK ((state = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'completed'::text])))
);


--
-- Name: module_topics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.module_topics (
    module_id uuid NOT NULL,
    topic_id uuid NOT NULL,
    "position" integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE module_topics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.module_topics IS 'A module''s track derives through its topics — no track column on modules.';


--
-- Name: module_transcripts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.module_transcripts (
    module_id uuid NOT NULL,
    transcript text NOT NULL,
    content_hash text NOT NULL,
    char_count integer NOT NULL,
    source text DEFAULT 'synthesia-captions'::text NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT module_transcripts_char_count_check CHECK ((char_count >= 0)),
    CONSTRAINT module_transcripts_source_check CHECK ((source = 'synthesia-captions'::text))
);


--
-- Name: TABLE module_transcripts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.module_transcripts IS 'Plain transcript text of a module''s video (from Synthesia SRT captions), persisted for AI question generation. Service-internal: the transcript answers the quiz, so learners must never read it.';


--
-- Name: modules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.modules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    title text NOT NULL,
    description text,
    learning_outcomes text[] DEFAULT '{}'::text[] NOT NULL,
    level_id uuid,
    video_source text DEFAULT 'synthesia'::text NOT NULL,
    video_url text,
    external_video_id text,
    duration_seconds integer NOT NULL,
    caption_url text,
    poster_url text,
    archive_url text,
    version integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp with time zone,
    retired_at timestamp with time zone,
    search tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((COALESCE(title, ''::text) || ' '::text) || COALESCE(description, ''::text)))) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    force_archive_playback boolean DEFAULT false NOT NULL,
    archive_bytes bigint,
    archive_verified_at timestamp with time zone,
    CONSTRAINT modules_archive_bytes_check CHECK (((archive_bytes IS NULL) OR (archive_bytes > 0))),
    CONSTRAINT modules_archive_verification_consistency CHECK ((((archive_verified_at IS NULL) AND (archive_bytes IS NULL)) OR ((archive_verified_at IS NOT NULL) AND (archive_bytes IS NOT NULL) AND (archive_url IS NOT NULL)))),
    CONSTRAINT modules_duration_seconds_check CHECK ((duration_seconds > 0)),
    CONSTRAINT modules_force_archive_needs_archive CHECK (((force_archive_playback = false) OR ((archive_url IS NOT NULL) AND (archive_verified_at IS NOT NULL)))),
    CONSTRAINT modules_published_consistency CHECK (((status = 'published'::text) = (published_at IS NOT NULL))),
    CONSTRAINT modules_retired_consistency CHECK (((status = 'retired'::text) = (retired_at IS NOT NULL))),
    CONSTRAINT modules_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT modules_version_check CHECK ((version > 0)),
    CONSTRAINT modules_video_ref CHECK (((video_url IS NOT NULL) OR (external_video_id IS NOT NULL))),
    CONSTRAINT modules_video_source_synthesia_only CHECK ((video_source = 'synthesia'::text))
);


--
-- Name: COLUMN modules.video_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.modules.video_source IS 'Always ''synthesia''. Vimeo and YouTube were removed in 021 — the player, the SDK and the per-source validation went with them, so a row holding either value would be unplayable. Kept as a column rather than dropped: a second source is a plausible future, and reintroducing the column would be a wider change than widening the CHECK.';


--
-- Name: COLUMN modules.external_video_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.modules.external_video_id IS 'Provider-side id (Synthesia/YouTube). The settled half of the old synthesia_video_map; in-flight proposals ride ingest_items.payload.';


--
-- Name: COLUMN modules.force_archive_playback; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.modules.force_archive_playback IS 'Play this module from its MP4 archive regardless of the global switch. For one broken embed. Has no effect without a verified archive — see modules_force_archive_needs_archive.';


--
-- Name: COLUMN modules.archive_verified_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.modules.archive_verified_at IS 'When the archive object was last confirmed to exist in Storage with a non-zero size. NULL means unverified, which is NOT the same as missing — it means nobody has looked. The fallback refuses to serve an unverified archive, because serving a 404 in place of a broken video is not a fallback.';


--
-- Name: notification_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.notification_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_key text NOT NULL,
    subject_key text NOT NULL,
    org_id uuid,
    subject_user_id uuid,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    raised_at timestamp with time zone DEFAULT now() NOT NULL,
    dismissed_at timestamp with time zone,
    dismissed_by uuid,
    CONSTRAINT notification_events_dismissal_consistency CHECK (((dismissed_at IS NULL) = (dismissed_by IS NULL)))
);


--
-- Name: TABLE notification_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.notification_events IS 'Every alert ever raised, dismissed or not. Append-only in spirit: dismissing sets a timestamp rather than deleting, so the panel has a history and a recurring problem is visible as a recurrence.';


--
-- Name: notification_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.notification_rules (
    key text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    threshold_days integer,
    threshold_pct integer,
    repeat_after_days integer DEFAULT 14 NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT notification_rules_repeat_after_days_check CHECK (((repeat_after_days >= 1) AND (repeat_after_days <= 365))),
    CONSTRAINT notification_rules_threshold_days_check CHECK (((threshold_days IS NULL) OR ((threshold_days >= 1) AND (threshold_days <= 365)))),
    CONSTRAINT notification_rules_threshold_pct_check CHECK (((threshold_pct IS NULL) OR ((threshold_pct >= 1) AND (threshold_pct <= 100))))
);


--
-- Name: TABLE notification_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.notification_rules IS 'One row per alert rule. Thresholds and the suppression window are settings, not constants. No INSERT policy: adding a rule needs code to evaluate it, so it is a migration.';


--
-- Name: organisations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.organisations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    created_by uuid,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    learner_seats integer DEFAULT 1 NOT NULL,
    operating_states payroll_iq.au_state[] DEFAULT '{}'::payroll_iq.au_state[] NOT NULL,
    billing_lane text DEFAULT 'none'::text NOT NULL,
    billing_state text DEFAULT 'active'::text NOT NULL,
    paid_through date,
    grace_ends_on date,
    stripe_customer_id text,
    stripe_subscription_id text,
    hubspot_invoice_ref text,
    seat_price_override_cents integer,
    CONSTRAINT organisations_billing_lane_valid CHECK ((billing_lane = ANY (ARRAY['stripe'::text, 'hubspot'::text, 'none'::text]))),
    CONSTRAINT organisations_billing_state_valid CHECK ((billing_state = ANY (ARRAY['active'::text, 'payment_overdue'::text, 'suspended'::text, 'cancelled'::text]))),
    CONSTRAINT organisations_learner_seats_positive CHECK ((learner_seats >= 1)),
    CONSTRAINT organisations_operating_states_sane CHECK (((array_length(operating_states, 1) IS NULL) OR (array_length(operating_states, 1) <= 8))),
    CONSTRAINT organisations_seat_price_override_positive CHECK (((seat_price_override_cents IS NULL) OR (seat_price_override_cents > 0))),
    CONSTRAINT organisations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text])))
);


--
-- Name: TABLE organisations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.organisations IS 'Tenant spine. Created by public signup (creator becomes its manager). One-person orgs are first-class: nothing may assume a team exists. No SSO/SCIM/domains/pricing — re-add with the feature that needs them.';


--
-- Name: COLUMN organisations.learner_seats; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.learner_seats IS 'Seats the org pays for. One seat = one active learner OR one open learner invite. Non-learning managers and admins occupy nothing.';


--
-- Name: COLUMN organisations.operating_states; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.operating_states IS 'States and territories this employer pays people in. Empty means not recorded, which resolves to general content only — NOT to all eight. Set by an admin; the learner inherits it.';


--
-- Name: COLUMN organisations.billing_lane; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.billing_lane IS 'Which system generated this org''s invoices (CONTEXT.md: one invoice, one origin). stripe = pay-now, hubspot = pay-by-invoice, none = pre-billing/grandfathered org that has never purchased. The lane is chosen by the buyer at purchase time and both lanes feed the SAME entitlement fields here — ADR 0001.';


--
-- Name: COLUMN organisations.billing_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.billing_state IS 'Billing lifecycle per CONTEXT.md: active | payment_overdue (grace window closed on an unpaid invoice) | suspended (learners locked out, manager alive with a pay-now prompt, nothing deleted) | cancelled (dormant, not destroyed: read-only manager shell, all data retained, reactivation is a fresh purchase). Distinct from `status`, the admin''s manual switch — see file header.';


--
-- Name: COLUMN organisations.paid_through; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.paid_through IS 'Last Sydney calendar date the org''s current paid term covers — never NULL after §9 of this migration (pre-billing orgs got a comped year from apply day). Renewal crons key off this; mark-paid extends it a full year from TERM START, not from the payment date.';


--
-- Name: COLUMN organisations.grace_ends_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.grace_ends_on IS 'End of the grace window (CONTEXT.md: 30 days from invoice issue; admin "extend grace" moves it). NULL when no window is running. Unpaid past this date ⇒ payment_overdue + suspended.';


--
-- Name: COLUMN organisations.stripe_customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.stripe_customer_id IS 'Stripe lane only. NULL on hubspot/none lanes — A4 forbids cross-writing, so a hubspot-lane org acquiring one is a bug.';


--
-- Name: COLUMN organisations.stripe_subscription_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.stripe_subscription_id IS 'Stripe lane only: the annual auto-renewing subscription. Cancel (G2) cancels it; nothing else touches it.';


--
-- Name: COLUMN organisations.hubspot_invoice_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.hubspot_invoice_ref IS 'HubSpot lane: the org''s most recent HubSpot invoice id, for the manager Billing page and reconciliation. Full history lives in `invoice_records`.';


--
-- Name: COLUMN organisations.seat_price_override_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.organisations.seat_price_override_cents IS 'Negotiated per-seat annual price (AUD cents, GST-inclusive) — a sales commitment that overrides the seat_tiers ladder for this org and survives ladder edits (CONTEXT.md: negotiated override). NULL = priced from the ladder. Set only via the admin Billing console; every change is recorded in pricing_events.';


--
-- Name: plan_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.plan_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    module_id uuid NOT NULL,
    topic_id uuid NOT NULL,
    week integer NOT NULL,
    "position" integer DEFAULT 1 NOT NULL,
    scheduled_date date NOT NULL,
    source text DEFAULT 'plan'::text NOT NULL,
    source_attempt_id uuid,
    added_at timestamp with time zone DEFAULT now() NOT NULL,
    removed_at timestamp with time zone,
    CONSTRAINT plan_items_position_check CHECK (("position" >= 1)),
    CONSTRAINT plan_items_remediation_has_source CHECK (((source <> 'remediation'::text) OR (source_attempt_id IS NOT NULL))),
    CONSTRAINT plan_items_source_check CHECK ((source = ANY (ARRAY['plan'::text, 'remediation'::text, 'pick'::text]))),
    CONSTRAINT plan_items_week_check CHECK (((week >= 1) AND (week <= 13)))
);


--
-- Name: TABLE plan_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.plan_items IS 'One row per scheduled module in a plan VERSION. source: plan (generator) | remediation (wrong answers on the linked attempt, written into the ACTIVE plan) | pick (learner-chosen). Soft-remove via removed_at; slot uniqueness ignores removed rows.';


--
-- Name: plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cycle_id uuid NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    rationale jsonb DEFAULT '{}'::jsonb NOT NULL,
    generator_inputs jsonb DEFAULT '{}'::jsonb NOT NULL,
    generator_version text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT plans_status_check CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text]))),
    CONSTRAINT plans_version_check CHECK ((version >= 1))
);


--
-- Name: TABLE plans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.plans IS 'Versioned (v2, from the program plan): AI-1 regenerations create a new version and supersede the old — rationale is the model''s explanation, generator_inputs the reproducibility record. The deterministic budget layer''s verdict is what ships; the AI is never the only thing between a learner and a valid plan.';


--
-- Name: platform_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.platform_settings (
    key text NOT NULL,
    value jsonb NOT NULL,
    description text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid
);


--
-- Name: TABLE platform_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.platform_settings IS 'Global operational switches, flipped by an admin at runtime. Not a config store: anything with structure gets its own table.';


--
-- Name: pricing_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.pricing_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor uuid,
    entity_kind text NOT NULL,
    entity_id text NOT NULL,
    before jsonb,
    after jsonb,
    at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE pricing_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.pricing_events IS 'Append-only audit of every pricing mutation: ladder edits, discount code changes, per-org negotiated overrides. Written only by service_role (admin server actions). Prices move real invoices — a mutation without a row here is a bug.';


--
-- Name: question_remediation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.question_remediation (
    question_id uuid NOT NULL,
    module_id uuid NOT NULL,
    priority integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT question_remediation_priority_check CHECK ((priority >= 1))
);


--
-- Name: TABLE question_remediation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.question_remediation IS 'Hand-curated overrides. Default remediation derives: question -> topic -> that topic''s published modules. Rows here pin specific modules ahead of the derivation, priority-ordered.';


--
-- Name: questions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.questions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    topic_id uuid NOT NULL,
    track text NOT NULL,
    difficulty text NOT NULL,
    question_text text NOT NULL,
    options jsonb NOT NULL,
    correct_answer jsonb NOT NULL,
    explanation text,
    mastery_weight numeric DEFAULT 1.0 NOT NULL,
    source text DEFAULT 'human'::text NOT NULL,
    status text DEFAULT 'live'::text NOT NULL,
    authored_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    generated_from_module_id uuid,
    source_transcript_hash text,
    CONSTRAINT questions_difficulty_check CHECK ((difficulty = ANY (ARRAY['easy'::text, 'medium'::text, 'hard'::text]))),
    CONSTRAINT questions_generated_ai_only CHECK (((generated_from_module_id IS NULL) OR (source = 'ai'::text))),
    CONSTRAINT questions_generated_has_hash CHECK (((generated_from_module_id IS NULL) OR (source_transcript_hash IS NOT NULL))),
    CONSTRAINT questions_mastery_weight_check CHECK ((mastery_weight > (0)::numeric)),
    CONSTRAINT questions_source_check CHECK ((source = ANY (ARRAY['human'::text, 'ai'::text]))),
    CONSTRAINT questions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'live'::text, 'retired'::text]))),
    CONSTRAINT questions_track_check CHECK ((track = ANY (ARRAY['payroll'::text, 'hr'::text])))
);


--
-- Name: COLUMN questions.topic_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.questions.topic_id IS 'Hard FK, on delete restrict — a mis-tagged question is an insert-time error, not a silent mis-scoring bug (archived 073).';


--
-- Name: COLUMN questions.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.questions.source IS 'human | ai. AI-3 drafts insert as source=''ai'', status=''draft'' — the admin approval gate (plan §1.4) is the transition to ''live''. The quiz engine reads status=''live'' ONLY; draft rows are unreachable by construction, not by UI.';


--
-- Name: COLUMN questions.generated_from_module_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.questions.generated_from_module_id IS 'AI provenance: the module whose transcript this question was generated from. Null for human-authored questions.';


--
-- Name: COLUMN questions.source_transcript_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.questions.source_transcript_hash IS 'SHA-256 of the transcript version the question was generated from. Pairs with generated_from_module_id for replacement-set detection.';


--
-- Name: quiz_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.quiz_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_id uuid NOT NULL,
    kind text NOT NULL,
    module_id uuid,
    topic_id uuid,
    question_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_at timestamp with time zone,
    score numeric,
    total integer,
    passed boolean,
    status text DEFAULT 'in_progress'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quiz_attempts_kind_check CHECK ((kind = ANY (ARRAY['diagnostic'::text, 'module'::text, 'topic'::text]))),
    CONSTRAINT quiz_attempts_module_kind CHECK (((kind = 'module'::text) = (module_id IS NOT NULL))),
    CONSTRAINT quiz_attempts_score_check CHECK (((score IS NULL) OR ((score >= (0)::numeric) AND (score <= (100)::numeric)))),
    CONSTRAINT quiz_attempts_status_check CHECK ((status = ANY (ARRAY['in_progress'::text, 'submitted'::text, 'abandoned'::text]))),
    CONSTRAINT quiz_attempts_status_consistency CHECK (((status = 'submitted'::text) = (submitted_at IS NOT NULL))),
    CONSTRAINT quiz_attempts_submitted_consistency CHECK (((submitted_at IS NULL) = (score IS NULL))),
    CONSTRAINT quiz_attempts_topic_kind CHECK (((topic_id IS NULL) OR (kind = 'topic'::text))),
    CONSTRAINT quiz_attempts_total_check CHECK (((total IS NULL) OR (total > 0)))
);


--
-- Name: TABLE quiz_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.quiz_attempts IS 'THE quiz engine. kind=diagnostic (onboarding assessment), kind=module (end-of-video — the shipped quiz per STUDENT_WORKFLOW line 8), kind=topic (engine-supported, unscheduled). question_ids is the ordered served-question snapshot; scores are percentages.';


--
-- Name: quiz_responses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.quiz_responses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    attempt_id uuid NOT NULL,
    question_id uuid NOT NULL,
    response jsonb NOT NULL,
    is_correct boolean NOT NULL,
    "position" integer NOT NULL,
    answered_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quiz_responses_position_check CHECK (("position" >= 1))
);


--
-- Name: seat_tiers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.seat_tiers (
    id text NOT NULL,
    name text NOT NULL,
    min_seats integer NOT NULL,
    max_seats integer,
    price_per_seat_cents integer,
    currency text DEFAULT 'AUD'::text NOT NULL,
    gst_inclusive boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT seat_tiers_check CHECK (((max_seats IS NULL) OR (max_seats >= min_seats))),
    CONSTRAINT seat_tiers_min_seats_check CHECK ((min_seats >= 1)),
    CONSTRAINT seat_tiers_price_per_seat_cents_check CHECK (((price_per_seat_cents IS NULL) OR (price_per_seat_cents > 0)))
);


--
-- Name: TABLE seat_tiers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.seat_tiers IS 'The published seat-price ladder (CONTEXT.md: Seat tier). Admin-editable; marketing, signup, checkout and invoicing all quote through lib/billing — never read a price from anywhere else. A ladder edit never touches a term already paid for (C3); it applies at each org''s next renewal. Edits are recorded in pricing_events.';


