    converted_at timestamp with time zone,
    CONSTRAINT signup_prospects_email_check CHECK ((email = lower(email)))
);


--
-- Name: TABLE signup_prospects; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.signup_prospects IS 'Signup funnel step-1 contacts (spec 026). Service-role only; see migration header.';


