);


--
-- Name: TABLE team_insights; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.team_insights IS 'AI-4 cache: latest row per org is the current summary. The manager table must render fully when this is stale or absent (plan E11).';


--
-- Name: topic_mastery; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.topic_mastery (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_id uuid NOT NULL,
    topic_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    score numeric NOT NULL,
    band text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT topic_mastery_band_check CHECK ((band = ANY (ARRAY['gap'::text, 'developing'::text, 'proficient'::text, 'mastered'::text]))),
    CONSTRAINT topic_mastery_score_check CHECK (((score >= (0)::numeric) AND (score <= (100)::numeric)))
);


--
-- Name: TABLE topic_mastery; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.topic_mastery IS 'Append-only snapshots per scoring attempt — current mastery is the latest row per (learner, topic); history feeds trajectory and cycle-over-cycle comparison. Deliberately NOT a mutable score cell.';


--
-- Name: topics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.topics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    description text,
    track text NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'live'::text NOT NULL,
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    parent_id uuid,
    state payroll_iq.au_state,
    CONSTRAINT topics_no_self_parent CHECK (((parent_id IS NULL) OR (parent_id <> id))),
    CONSTRAINT topics_retired_consistency CHECK (((status = 'retired'::text) = (retired_at IS NOT NULL))),
    CONSTRAINT topics_state_requires_parent CHECK (((state IS NULL) OR (parent_id IS NOT NULL))),
    CONSTRAINT topics_status_check CHECK ((status = ANY (ARRAY['live'::text, 'retired'::text]))),
    CONSTRAINT topics_track_check CHECK ((track = ANY (ARRAY['payroll'::text, 'hr'::text])))
);


--
-- Name: TABLE topics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.topics IS 'THE topic identity — everything references topics.id, FK-enforced. Flat list (v2 dropped the parent hierarchy: no epic reads it). The prototype''s free-text topic_tag join key does not exist here.';


--
-- Name: COLUMN topics.parent_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.topics.parent_id IS 'Parent topic, or NULL for a top-level topic. AT MOST ONE LEVEL DEEP - enforced by topics_one_level_deep(). ON DELETE RESTRICT because a parent with children is not something to remove by accident; retire it instead.';


--
-- Name: COLUMN topics.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.topics.state IS 'The state this sub-topic covers, or NULL for content everyone sees. Only a sub-topic may carry one (topics_state_requires_parent). NOTE: per the 90-day plan spec section 3 a state child is NOT a separate scoring topic - it is rolled up to its parent in buildQuestionPoolForTrack.';


--
-- Name: topic_serving_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW payroll_iq.topic_serving_readiness WITH (security_invoker='true') AS
 SELECT t.id AS topic_id,
    t.slug,
    t.parent_id,
    t.state,
    t.status,
    count(q.id) FILTER (WHERE (q.status = 'live'::text)) AS live_questions,
    (count(q.id) FILTER (WHERE (q.status = 'live'::text)) >= 5) AS meets_quiz_floor
   FROM (payroll_iq.topics t
     LEFT JOIN payroll_iq.questions q ON ((q.topic_id = t.id)))
  GROUP BY t.id, t.slug, t.parent_id, t.state, t.status;


--
-- Name: VIEW topic_serving_readiness; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW payroll_iq.topic_serving_readiness IS 'Live question count per topic, and whether it clears the topic-quiz serving floor of 5. A state sub-topic below the floor must stay invisible to learners: it would produce a quiz that cannot be sat, and lengthen the diagnostic while contributing nothing. security_invoker: a non-admin caller gets zeros, so learner paths must read it through the service role (getTopicReadinessForServing).';


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.users (
    id uuid NOT NULL,
    org_id uuid,
    email text NOT NULL,
    full_name text,
    phone text,
    role text DEFAULT 'learner'::text NOT NULL,
    content_track text,
    weekly_minutes integer,
    diagnostic_completed_at timestamp with time zone,
    preferences jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_learner boolean DEFAULT true NOT NULL,
    last_seen_at timestamp with time zone,
    CONSTRAINT users_content_track_check CHECK (((content_track IS NULL) OR (content_track = ANY (ARRAY['payroll'::text, 'hr'::text])))),
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'manager'::text, 'learner'::text]))),
    CONSTRAINT users_status_check CHECK ((status = ANY (ARRAY['active'::text, 'deactivated'::text]))),
    CONSTRAINT users_weekly_minutes_check CHECK (((weekly_minutes IS NULL) OR (weekly_minutes = ANY (ARRAY[10, 15, 20, 30, 40, 50, 60, 90, 120]))))
);


--
-- Name: COLUMN users.role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.users.role IS 'Three-tier role. `admin` is APA platform staff with cross-organisation access via payroll_iq.is_admin(); as of 025 an admin MAY also belong to an organisation, so admin no longer implies org_id IS NULL. Switching surfaces is a `pi_profile` cookie in the app, NEVER a role change — every surface keeps its own guard.';


--
-- Name: COLUMN users.diagnostic_completed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.users.diagnostic_completed_at IS 'Onboarding gate: null routes every learner surface to /onboarding (track + weekly commitment + diagnostic). Set once, on first diagnostic submission.';


--
-- Name: COLUMN users.is_learner; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.users.is_learner IS 'Whether this account is a learner — has a plan, occupies a learner seat, appears in the team-progress roster. As of 026 this is independent of `role`, so an admin may be a learner too; before 026 a CHECK forbade that combination and a promoted manager silently left the roster of the organisation they manage.';


--
-- Name: COLUMN users.last_seen_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN payroll_iq.users.last_seen_at IS 'Last time this user was observed on an authenticated page, throttled to at most hourly. NOT auth.users.last_sign_in_at, which long-lived sessions make useless as an engagement signal. NULL means never observed since 023 shipped — which is not the same as never active, and the quiet-manager rule treats it accordingly.';


--
-- Name: watch_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE payroll_iq.watch_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_id uuid NOT NULL,
    module_id uuid NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    seconds_watched integer DEFAULT 0 NOT NULL,
    max_position integer DEFAULT 0 NOT NULL,
    speed_avg numeric(3,2),
    reason_ended text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT watch_sessions_ended_consistency CHECK (((ended_at IS NULL) = (reason_ended IS NULL))),
    CONSTRAINT watch_sessions_max_position_check CHECK ((max_position >= 0)),
    CONSTRAINT watch_sessions_reason_ended_check CHECK (((reason_ended IS NULL) OR (reason_ended = ANY (ARRAY['finished'::text, 'paused'::text, 'closed_tab'::text])))),
    CONSTRAINT watch_sessions_seconds_watched_check CHECK ((seconds_watched >= 0)),
    CONSTRAINT watch_sessions_speed_avg_check CHECK (((speed_avg IS NULL) OR ((speed_avg >= 0.5) AND (speed_avg <= 2.0))))
);


--
-- Name: TABLE watch_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE payroll_iq.watch_sessions IS 'Watch evidence. Feeds observed_watch completion AND the manager''s primary metric — time committed vs time completed is aggregated from here (program plan E11).';


