--
-- Name: invites invites_seat_capacity_insert; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER invites_seat_capacity_insert AFTER INSERT ON payroll_iq.invites FOR EACH ROW WHEN ((new.is_learner AND (new.released_at IS NULL) AND (new.accepted_at IS NULL) AND (new.expires_at > now()))) EXECUTE FUNCTION payroll_iq.enforce_seat_capacity();


--
-- Name: invites invites_seat_capacity_update; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER invites_seat_capacity_update AFTER UPDATE ON payroll_iq.invites FOR EACH ROW WHEN ((new.is_learner AND (new.released_at IS NULL) AND (new.accepted_at IS NULL) AND (new.expires_at > now()) AND ((old.is_learner IS DISTINCT FROM new.is_learner) OR (old.released_at IS DISTINCT FROM new.released_at) OR (old.expires_at IS DISTINCT FROM new.expires_at) OR (old.org_id IS DISTINCT FROM new.org_id)))) EXECUTE FUNCTION payroll_iq.enforce_seat_capacity();


